def transform(grid):
    from collections import Counter, defaultdict
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            comp = []
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            objects.append((color, comp))

    frame = max(objects, key=lambda o: len(o[1]))
    fc = frame[0]
    top = min(y for y,x in frame[1])
    bottom = max(y for y,x in frame[1])
    left = min(x for y,x in frame[1])
    right = max(x for y,x in frame[1])
    out = [row[left:right+1] for row in grid[top:bottom+1]]

    def normalize(comp):
        my = min(y for y,x in comp)
        mx = min(x for y,x in comp)
        return frozenset((y-my,x-mx) for y,x in comp)

    def category(comp):
        s = normalize(comp)
        hh = max(y for y,x in s)+1
        ww = max(x for y,x in s)+1
        transforms = [
            lambda y,x: (hh-1-y,x),
            lambda y,x: (y,ww-1-x),
            lambda y,x: (x,y),
            lambda y,x: (ww-1-x,hh-1-y),
        ]
        nsym = 0
        for f in transforms:
            t = {(f(y,x)) for y,x in s}
            my = min(y for y,x in t)
            mx = min(x for y,x in t)
            if frozenset((y-my,x-mx) for y,x in t) == s:
                nsym += 1
        return len(s), nsym

    candidates = defaultdict(Counter)
    for color, comp in objects:
        if color in (bg, fc):
            continue
        if any(top <= y <= bottom and left <= x <= right for y,x in comp):
            continue
        candidates[category(comp)][color] += 1

    local_seen = set(frame[1])
    for y in range(top, bottom+1):
        for x in range(left, right+1):
            if grid[y][x] != bg or (y,x) in local_seen:
                continue
            comp = []
            stack = [(y,x)]
            local_seen.add((y,x))
            while stack:
                a,b = stack.pop()
                comp.append((a,b))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx = a+dy,b+dx
                    if top <= ny <= bottom and left <= nx <= right and (ny,nx) not in local_seen and grid[ny][nx] == bg:
                        local_seen.add((ny,nx))
                        stack.append((ny,nx))
            counts = candidates.get(category(comp))
            if counts:
                color = max(counts, key=lambda c: (counts[c], c))
                for a,b in comp:
                    out[a-top][b-left] = color
    return out
